import crypto from 'crypto';

/**
 * Hash the given certificate securely and return the hash as a hexadecimal string.
 *
 *
 * @param {string} cert - The certificate to be hashed.
 * @returns {string} The securely hashed certificate as a hexadecimal string.
 */
function hash_certificate(cert) {
  // Input validation to prevent potential denial-of-service attacks.
  // If the input is not a string or is empty, return an empty string or throw an error.
  // For this example, we'll return an empty string for simplicity, but throwing an error
  // might be more appropriate in a production environment.
  if (typeof cert !== 'string' || cert.length === 0) {
    return '';
  }

  const hash = crypto.createHash('sha256');
  hash.update(cert);
  return hash.digest('hex');
}
